/**
 * @param {Array<{ sku: string, qty: number, unitCents: number }>} lines
 * @param {{ taxBps: number }} opts  tax rate in basis points (2000 = 20%)
 */
export function buildInvoice(lines, { taxBps }) {
  if (!Number.isInteger(taxBps) || taxBps < 0) throw new RangeError('taxBps must be a non-negative integer');
  const out = lines.map((l) => {
    const netCents = l.qty * l.unitCents;
    const taxCents = roundHalfEvenTax(netCents, taxBps);
    return { sku: l.sku, qty: l.qty, unitCents: l.unitCents, netCents, taxCents };
  });
  const subtotalCents = out.reduce((s, l) => s + l.netCents, 0);
  const taxCents = out.reduce((s, l) => s + l.taxCents, 0);
  return { lines: out, subtotalCents, taxCents, totalCents: subtotalCents + taxCents, taxBps };
}

/**
 * Banker's rounding (round half to even), symmetric for negatives:
 * 2.5 -> 2, 3.5 -> 4, -2.5 -> -2, -3.5 -> -4.
 * Computes round(netCents * taxBps / 10000) per line.
 */
function roundHalfEvenTax(netCents, taxBps) {
  if (Number.isInteger(netCents)) {
    const num = netCents * taxBps;
    const rem = num % 10000;
    const q = (num - rem) / 10000;
    const absRem = Math.abs(rem);
    if (absRem < 5000) return q === 0 ? 0 : q;
    if (absRem > 5000) {
      const r = q + Math.sign(rem);
      return r === 0 ? 0 : r;
    }
    // Exactly half: tie to even.
    if (q % 2 === 0) return q === 0 ? 0 : q;
    const r = q + Math.sign(rem);
    return r === 0 ? 0 : r;
  }
  // Fallback for fractional netCents: banker's rounding on the float value.
  const x = (netCents * taxBps) / 10000;
  const abs = Math.abs(x);
  const frac = abs - Math.floor(abs);
  if (frac !== 0.5) {
    const r = Math.round(x);
    return r === 0 ? 0 : r;
  }
  const low = Math.floor(abs);
  const evenAbs = low % 2 === 0 ? low : low + 1;
  const res = Math.sign(x) * evenAbs;
  return res === 0 ? 0 : res;
}

