 * Round half to even (banker's rounding), symmetric for negatives:
 * 2.5 -> 2, 3.5 -> 4, -2.5 -> -2, -3.5 -> -4.
 * Anything not exactly on a half rounds to nearest.
 * Used by: invoice.mjs (line tax).
 */
export function roundHalfEven(x) {
  if (!Number.isFinite(x)) return Math.round(x);
  if (x === 0) return 0;
  const sign = x < 0 ? -1 : 1;
  const abs = Math.abs(x);
  const f = Math.floor(abs);
  const d = abs - f;
  let r;
  if (d < 0.5) r = sign * f;
  else if (d > 0.5) r = sign * (f + 1);
  else r = f % 2 === 0 ? sign * f : sign * (f + 1);
  return r === 0 ? 0 : r;
}

